```ctl
//#CTL2
function integer transform() {
    integer bits = 0;
    string labels = "";
    boolean accountChanged;

    if (isnull($in.0.recipient_account)) {
        accountChanged = !isnull($in.1.recipient_account);
    } else if (isnull($in.1.recipient_account)) {
        accountChanged = true;
